<?php require_once '../functions.php';need_admin();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){if(isset($_POST['delete'])){$pdo->prepare('DELETE FROM diseases WHERE id=?')->execute([(int)$_POST['id']]);$msg='Penyakit dihapus.';}else{$id=(int)($_POST['id']??0);$v=[trim($_POST['code']),trim($_POST['name']),trim($_POST['scientific_name']),trim($_POST['description']),trim($_POST['advice']),isset($_POST['active'])?1:0];if($id)$pdo->prepare('UPDATE diseases SET code=?,name=?,scientific_name=?,description=?,advice=?,active=? WHERE id=?')->execute([...$v,$id]);else$pdo->prepare('INSERT INTO diseases(code,name,scientific_name,description,advice,active) VALUES(?,?,?,?,?,?)')->execute($v);$msg='Penyakit tersimpan.';}}$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM diseases WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}$rows=$pdo->query('SELECT * FROM diseases ORDER BY code')->fetchAll();header_html('Kelola penyakit');include '_nav.php';?><section class="page-head"><span class="eyebrow">BASIS PENGETAHUAN</span><h1>Data penyakit</h1><p>Informasi penyakit yang bisa dikenali oleh sistem.</p></section><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><section class="card admin-form"><h2><?=$edit?'Ubah penyakit':'Tambah penyakit'?></h2><form method="post" class="form form-grid"><input type="hidden" name="id" value="<?=$edit['id']??''?>"><label>Kode<input name="code" value="<?=e($edit['code']??'')?>" required placeholder="P001"></label><label>Nama penyakit<input name="name" value="<?=e($edit['name']??'')?>" required></label><label>Nama ilmiah<input name="scientific_name" value="<?=e($edit['scientific_name']??'')?>"></label><label class="span2">Deskripsi<textarea name="description" rows="2"><?=e($edit['description']??'')?></textarea></label><label class="span2">Saran tindak lanjut<textarea name="advice" rows="2"><?=e($edit['advice']??'')?></textarea></label><label class="inline"><input type="checkbox" name="active" <?=!isset($edit['active'])||$edit['active']?'checked':''?>> Aktif</label><button class="button">Simpan penyakit</button></form></section><div class="table-wrap card"><table><thead><tr><th>Kode</th><th>Penyakit</th><th>Nama ilmiah</th><th>Aktif</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['code'])?></td><td><b><?=e($r['name'])?></b><small class="block"><?=e($r['description'])?></small></td><td><?=e($r['scientific_name'])?></td><td><?=$r['active']?'Ya':'Tidak'?></td><td><a href="?edit=<?=$r['id']?>">Ubah</a> <form class="inline-form" method="post" onsubmit="return confirm('Hapus penyakit ini?')"><input type="hidden" name="id" value="<?=$r['id']?>"><button name="delete" value="1" class="link-danger">Hapus</button></form></td></tr><?php endforeach;?></tbody></table></div><?php footer_html();?>
